function goodDaysToRobBank(security, time) {
  const n = security.length;
  const rises = new Array(n).fill(0);
  const falls = new Array(n).fill(0);
  for (let i = 1; i < n; i++) {
    rises[i] = rises[i - 1] + (security[i] > security[i - 1] ? 1 : 0);
    falls[i] = falls[i - 1] + (security[i] < security[i - 1] ? 1 : 0);
  }
  const days = [];
  for (let i = time; i + time < n; i++) {
    const noRiseBefore = rises[i] - rises[i - time] === 0;
    const noFallAfter = falls[i + time] - falls[i] === 0;
    if (noRiseBefore && noFallAfter) {
      days.push(i);
    }
  }
  return days;
}

