function goodDaysToRobBank(security, time) {
  const result = [];
  for (let day = 0; day < security.length; day++) {
    if (day - time < 0 || day + time >= security.length) continue;
    let good = true;
    for (let j = day - time; j < day; j++) if (security[j] < security[j + 1]) good = false;
    for (let j = day; j < day + time; j++) if (security[j] > security[j + 1]) good = false;
    if (good) result.push(day);
  }
  return result;
}

