function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10);
    const top = rand() < 0.5 ? 3 : 9;
    const security = Array.from({ length: n }, () => int(0, top));
    const time = rand() < 0.1 ? int(5, 12) : int(0, 3);
    return [security, time];
  }
  // Long runs that go down, stay flat or go up create valleys, so good days exist for larger windows.
  const n = int(1800, 2000);
  const security = [];
  let value = int(0, 100000);
  while (security.length < n) {
    const length = int(1, 60);
    const direction = int(-1, 1);
    const step = rand() < 0.5 ? 1 : int(1, 2000);
    for (let k = 0; k < length && security.length < n; k++) {
      value = Math.min(100000, Math.max(0, value + direction * int(0, step)));
      security.push(value);
    }
  }
  const time = rand() < 0.15 ? int(1000, 100000) : int(0, 25);
  return [security, time];
}
